'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert/strict'),zlib=require('zlib'),crypto=require('crypto');
require('../Companion Files/session-bundle.js');const B=globalThis.MIDIR_BUNDLE;
const fixtures=process.argv[2];if(!fixtures)throw Error('Supply extracted Midir 49.a fixture directory');
const file=(name,b)=>new File([b],name),from=name=>file(name,fs.readFileSync(path.join(fixtures,name)));
async function results(f,opts){const z=await B.open(f,opts);const all=[];for await(const x of z.reports())all.push(x);return all;}
// Minimal classic ZIP builder used only for adversarial headers/descriptors.
function zip(entries){let pos=0;const locals=[],centrals=[];for(const e of entries){const name=Buffer.from(e.name),raw=Buffer.from(e.body||'x'),method=e.method??0,flags=e.flags??2048,packed=method===8?zlib.deflateRawSync(raw):raw,crc=e.crc??B.crc(raw),length=e.length??raw.length;const a=Buffer.alloc(30),c=Buffer.alloc(46);a.writeUInt32LE(0x04034b50);a.writeUInt16LE(20,4);a.writeUInt16LE(flags,6);a.writeUInt16LE(method,8);if(!(flags&8)){a.writeUInt32LE(crc,14);a.writeUInt32LE(packed.length,18);a.writeUInt32LE(length,22)}a.writeUInt16LE(name.length,26);c.writeUInt32LE(0x02014b50);c.writeUInt16LE(20,4);c.writeUInt16LE(20,6);c.writeUInt16LE(flags,8);c.writeUInt16LE(method,10);c.writeUInt32LE(crc,16);c.writeUInt32LE(packed.length,20);c.writeUInt32LE(length,24);c.writeUInt16LE(name.length,28);c.writeUInt32LE(e.attr??0,38);c.writeUInt32LE(pos,42);let desc=Buffer.alloc(0);if(flags&8){desc=Buffer.alloc(16);desc.writeUInt32LE(0x08074b50);desc.writeUInt32LE(crc,4);desc.writeUInt32LE(packed.length,8);desc.writeUInt32LE(length,12)}locals.push(a,name,packed,desc);centrals.push(c,name);pos+=a.length+name.length+packed.length+desc.length}const central=Buffer.concat(centrals),end=Buffer.alloc(22);end.writeUInt32LE(0x06054b50);end.writeUInt16LE(entries.length,8);end.writeUInt16LE(entries.length,10);end.writeUInt32LE(central.length,12);end.writeUInt32LE(pos,16);return file('synthetic.zip',Buffer.concat([...locals,central,end]));}
(async()=>{const expected={'single.zip':1,'standard.zip':3,'store.zip':3,'overlap-a.zip':2,'overlap-b.zip':2,'one-player.zip':1,'legacy.zip':1,'large.zip':128,'retired-49-json.zip':3};const items={};for(const [n,num] of Object.entries(expected)){const list=await results(from(n));assert.equal(list.length,num);assert(!list.some(x=>x.error));if(n==='retired-49-json.zip')assert(list.every(x=>x.unsupported));else for(const x of list){assert(x.html&&x.fileHash);assert.equal(crypto.createHash('sha256').update(x.html,'utf8').digest('hex'),x.fileHash)}items[n]=list;}
 assert.equal(items['single.zip'][0].html,fs.readFileSync(path.join(fixtures,'individual.html'),'utf8'));assert.deepEqual(items['standard.zip'].map(x=>x.fileHash),items['store.zip'].map(x=>x.fileHash));assert.equal(items['one-player.zip'][0].identity.id,items['single.zip'][0].identity.id);assert.notEqual(items['one-player.zip'][0].identity.scopeKey,items['single.zip'][0].identity.scopeKey);assert.equal(new Set([...items['overlap-a.zip'],...items['overlap-b.zip']].map(x=>x.identity.id)).size,3);assert.equal(items['legacy.zip'][0].identity,null);assert(items['large.zip'].some(x=>JSON.parse(B.extract(x.html)).damageHitEvents.length===6000));console.log('PASS 9 producer fixtures, 128-report batch, exact original HTML and hash parity');
 const html=items['legacy.zip'][0].html;for(const method of [0,8]){const a=await results(zip([{name:'nested/例.html',body:html,method,flags:2056}]));assert.equal(a[0].html,html)}
 for(const [entries,re] of [ [[{name:'../a.html'}],/Unsafe/], [[{name:'/a.html'}],/Unsafe/], [[{name:'a\\b.html'}],/Unsafe/], [[{name:'A.html'},{name:'a.html'}],/Duplicate/], [[{name:'é.html'},{name:'e\u0301.html'}],/Duplicate/], [[{name:'link.html',attr:0xa0000000}],/links/], [[{name:'a.html',flags:2049}],/flags/], [[{name:'a.html',method:99}],/compression/], [[{name:'large.html',method:8,length:91*1024*1024}],/limit/], [[{name:'a.zip'}],/Nested/], [[{name:'manifest.json',body:'{}'},{name:'a.html',body:html}],/manifest/]])await assert.rejects(()=>B.open(zip(entries)),re);
 for(const [entry,re] of [[{name:'a.html',body:html,crc:0},/CRC/],[{name:'a.html',body:html,method:8,length:3},/actual output/],[{name:'a.html',body:html,method:8,length:Buffer.byteLength(html)+1},/actual size/]]){const a=await results(zip([entry]));assert.match(a[0].error,re)}
 const orig=globalThis.crypto;Object.defineProperty(globalThis,'crypto',{configurable:true,value:undefined});for(const x of ['','abc','예시 Ω','x'.repeat(1024*1024+13)])assert.equal(await B.sha(x),crypto.createHash('sha256').update(x).digest('hex'));Object.defineProperty(globalThis,'crypto',{configurable:true,value:orig});console.log('PASS ZIP path/flag/link/CRC/actual-size/declared-size/manifest checks; descriptors and SHA fallback');
})().catch(e=>{console.error(e);process.exitCode=1});
